 static final class ToolbarIcon extends android.graphics.drawable.Drawable {
  final android.graphics.Paint paint=new android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG);final String action;
  ToolbarIcon(String title){action=title.toLowerCase(Locale.ROOT);paint.setColor(0xffd9f9e6);paint.setStyle(android.graphics.Paint.Style.STROKE);paint.setStrokeWidth(1.8f);paint.setStrokeCap(android.graphics.Paint.Cap.ROUND);paint.setStrokeJoin(android.graphics.Paint.Join.ROUND);}
  void line(android.graphics.Canvas c,float...v){android.graphics.Path p=new android.graphics.Path();p.moveTo(v[0],v[1]);for(int i=2;i<v.length;i+=2)p.lineTo(v[i],v[i+1]);c.drawPath(p,paint);}
  @Override public void draw(android.graphics.Canvas canvas){android.graphics.Rect b=getBounds();int save=canvas.save();canvas.translate(b.left,b.top);canvas.scale(b.width()/24f,b.height()/24f);
   if(action.startsWith("toolbar:")){if(action.contains("labels")){line(canvas,8,5,21,5);line(canvas,8,12,21,12);line(canvas,8,19,21,19);canvas.drawCircle(3,5,1,paint);canvas.drawCircle(3,12,1,paint);canvas.drawCircle(3,19,1,paint);}else{canvas.drawRoundRect(3,3,9,9,1,1,paint);canvas.drawRoundRect(15,3,21,9,1,1,paint);canvas.drawRoundRect(3,15,9,21,1,1,paint);canvas.drawRoundRect(15,15,21,21,1,1,paint);}}
   else if(action.contains("appearance")){canvas.drawCircle(12,12,9,paint);canvas.drawCircle(9,8,1,paint);canvas.drawCircle(15,8,1,paint);canvas.drawCircle(7,13,1,paint);line(canvas,15,20,15,15,20,15);}
   else if(action.contains("stop")){canvas.drawRoundRect(5,5,19,19,2,2,paint);}
   else if(action.contains("hide")||action.contains("show")){android.graphics.Path eye=new android.graphics.Path();eye.moveTo(2,12);eye.cubicTo(7,3,17,3,22,12);eye.cubicTo(17,21,7,21,2,12);canvas.drawPath(eye,paint);canvas.drawCircle(12,12,3,paint);if(action.contains("show"))line(canvas,3,3,21,21);}
   else if(action.contains("joystick")||action.contains("control")){canvas.drawRoundRect(2,6,22,19,5,5,paint);line(canvas,7,10,7,16);line(canvas,4,13,10,13);canvas.drawCircle(16,11,1,paint);canvas.drawCircle(19,15,1,paint);}
   else if(action.contains("switch")){line(canvas,3,7,20,7,16,3);line(canvas,21,17,4,17,8,21);}
   else if(action.contains("save")){line(canvas,3,3,17,3,21,7,21,21,3,21,3,3);line(canvas,7,3,7,9,16,9,16,3);line(canvas,7,21,7,14,17,14,17,21);if(action.contains("as")){paint.setStyle(android.graphics.Paint.Style.FILL);canvas.drawCircle(18,6,5,paint);paint.setColor(0xff174a34);paint.setStyle(android.graphics.Paint.Style.STROKE);line(canvas,18,3.5f,18,8.5f);line(canvas,15.5f,6,20.5f,6);paint.setColor(0xffd9f9e6);}}
   else if(action.contains("load")){line(canvas,3,8,3,4,10,4,13,7,21,7,21,20,3,20,3,8);line(canvas,12,10,12,17);line(canvas,8,14,12,18,16,14);}
   else {line(canvas,14,4,6,12,14,20);line(canvas,6,12,22,12);}
   canvas.restoreToCount(save);
  }
  @Override public void setAlpha(int alpha){paint.setAlpha(alpha);invalidateSelf();}
  @Override public void setColorFilter(android.graphics.ColorFilter filter){paint.setColorFilter(filter);invalidateSelf();}
  @Override public int getOpacity(){return android.graphics.PixelFormat.TRANSLUCENT;}
 }

