  leaveDialog=new AlertDialog.Builder(this).setTitle("Leave the game?").setMessage(host?"Return to Co-op? Current progress will be checkpointed before leaving. Connected players will be disconnected.":"Leave this session and return to Co-op? Other players can keep playing.").setNegativeButton("Keep playing",null).setPositiveButton("Leave game",(d,w)->performLeavePlayerToCoop()).create();
